/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// UI builder required for validating and list partameters at initialisation
/// </summary>
public class METVendOpenItemsUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField numOfTasks, vendAccountNum, vendLegalEntityId;
    DialogField recList;

}

Method.Source:
/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Post build maps the dialog fields to contract
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    numOfTasks = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getNumOfTasks));
    recList = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getRecList));
    vendLegalEntityId = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getVendLegalEntityId));
    vendAccountNum = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getVendAccountNum));
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// postRun allows validation and hiding of methods
    /// </summary>
    public void postRun()
    {
        super();
    
        // register overrides for form control events
        numOfTasks.registerOverrideMethod(methodstr(FormIntControl, validate),
                methodstr(METVendOpenItemsUIBuilder, validateNumOfThreads), this);
        
        vendLegalEntityId.registerOverrideMethod(methodstr(FormStringControl, lookup),
                methodstr(METVendOpenItemsUIBuilder, lookupLegalEntity), this);
        vendLegalEntityId.registerOverrideMethod(methodstr(FormStringControl, modified),
                methodstr(METVendOpenItemsUIBuilder, modifiedLegalEntity), this);

        vendAccountNum.registerOverrideMethod(methodstr(FormStringControl, lookup),
                methodstr(METVendOpenItemsUIBuilder, lookupVendAccountNum), this);

        recList.visible(false);
    }

   /// <summary>
   /// MPJ_5046_MetpayInterfaces 05/05/2021
   /// Validating number of tasks given
   /// </summary>
   /// <param name = "_numOfTasks">Number of tasks</param>
   /// <returns>true or false</returns>
   public boolean validateNumOfThreads(FormIntControl _numOfTasks)
   {
       if (_numOfTasks.value() <= 0)
       {
           error("@MET:VendOpenItemsBatchTasks");
           return false;
       }

       return true;
   }

    /// <summary>
    /// Legal entity lookup in VendOpenItems table
    /// </summary>
    /// <param name = "_formStringControl">form string control </param>
    public void lookupLegalEntity(FormStringControl _formStringControl)
    {
        SysTableLookup sysTableLookUp;
        QueryBuildDataSource qbds;
        Query query = new Query();

        qbds = query.addDataSource(tableNum(DataArea));

        sysTableLookUp = SysTableLookup::newParameters(tableNum(DataArea), _formStringControl, true);

        sysTableLookUp.addSelectionField(fieldNum(DataArea, Id)) ;
        sysTableLookUp.addLookupfield(fieldNum(DataArea, Id)) ;
        sysTableLookUp.addLookupfield(fieldNum(DataArea, Name));
        
        sysTableLookUp.parmQuery(query);
        sysTableLookUp.performFormLookup();
    }

/// <summary>
/// Legal entity modified value
/// </summary>
/// <param name = "_formStringControl">form string control </param>
/// <returns>Boolean value</returns>
public boolean modifiedLegalEntity(FormStringControl _formStringControl)
{
    boolean ret = _formStringControl.modified();
    if(ret)
    {
        vendAccountNum.value('');
    }
    return ret;
    
}

/// <summary>
/// Lookup vendor account number
/// </summary>
/// <param name = "_formStringControl">Form string control</param>
public void lookupVendAccountNum(FormStringControl _formStringControl)
{
    VendTable::lookupVendor(_formStringControl, vendLegalEntityId.value());
}
